<?php
namespace App\Modules\Orders\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Orders\Domain\Models\SalesOrder;use Illuminate\Http\Request;use Inertia\Inertia;use Inertia\Response;
class ListSalesOrdersController extends Controller {public function __invoke(Request $request):Response{abort_unless($request->user()->hasPermission('orders.view'),403);$view=(string)$request->query('view','all');$query=SalesOrder::query()->with('customer:id,name')->latest('due_at');$query->when($view==='upcoming',fn($q)=>$q->whereBetween('due_at',[now(),now()->addHours(24)])->whereNotIn('status',['delivered','cancelled']))->when($view==='overdue',fn($q)=>$q->where('due_at','<',now())->whereNotIn('status',['delivered','cancelled']))->when($view==='production',fn($q)=>$q->whereIn('status',['pending_production','in_production']))->when($view==='ready',fn($q)=>$q->where('status','ready'));return Inertia::render('orders/Index',['orders'=>$query->paginate(25)->withQueryString()->through(fn($o)=>[...$o->only(['id','document_number','total','advance_amount','balance_amount']),'customer'=>$o->customer->name,'due_at'=>$o->due_at->format('Y-m-d H:i'),'priority'=>$o->priority->label(),'status'=>$o->status->value,'status_label'=>$o->status->label()]),'view'=>$view,'canManage'=>$request->user()->hasPermission('orders.manage')]);}}
